@@ -199,21 +209,28 @@ void PasswordsModel::populate()
     beginResetModel();
     mRoot = std::make_unique<Node>();
     mRoot->name = mPassStore.absolutePath();
-    populateDir(mPassStore, mRoot.get());
+    populateDir(mPassStore, mRoot.get(), QStringLiteral("*.gpg"));
+    if (mPassageStore.exists()) {
+        populateDir(mPassageStore, mRoot.get(), QStringLiteral("*.age"));
+    }
     endResetModel();
 }

-void PasswordsModel::populateDir(const QDir &dir, Node *parent)
+void PasswordsModel::populateDir(const QDir &dir, Node *parent, const QString &filter)
 {
     mWatcher.addPath(dir.absolutePath());
-    auto entries = dir.entryInfoList({QStringLiteral("*.gpg")}, QDir::Files, QDir::NoSort);
+    auto entries = dir.entryInfoList({filter}, QDir::Files, QDir::NoSort);
     for (const auto &entry : qAsConst(entries)) {
-        new Node(entry.completeBaseName(), PasswordEntry, parent);
+        auto node = new Node(entry.completeBaseName(), PasswordEntry, parent);
+        node->filePath = entry.absoluteFilePath();
     }
     entries = dir.entryInfoList(QDir::Dirs | QDir::NoDotAndDotDot, QDir::NoSort);
     for (const auto &entry : qAsConst(entries)) {
-        auto node = new Node(entry.fileName(), FolderEntry, parent);
-        populateDir(entry.absoluteFilePath(), node);
+        const auto it = std::find_if(parent->children.cbegin(), parent->children.cend(), [&entry](const auto &child) {
+            return child->type == FolderEntry && child->name == entry.fileName();
+        });
+        auto node = it != parent->children.cend() ? it->get() : new Node(entry.fileName(), FolderEntry, parent);
+        populateDir(entry.absoluteFilePath(), node, filter);
     }
 }

