-        }
+        handlePlainText(plainText);
     });

     const auto error = decryptJob->start(file.readAll());
@@ -106,6 +100,51 @@ void ProviderBase::start()
     }
 }

+void ProviderBase::startPassage()
+{
+    auto name = PasswordsModel::passageStore().relativeFilePath(mPath);
+    name.chop(4); // ".age"
+
+    auto process = new QProcess(this);
+    connect(process, &QProcess::errorOccurred, this, [this, process](QProcess::ProcessError error) {
+        if (error == QProcess::FailedToStart) {
+            qCWarning(PLASMAPASS_LOG, "Failed to start passage: %s", qUtf8Printable(process->errorString()));
+            setError(i18n("Failed to decrypt password: %1", process->errorString()));
+            process->deleteLater();
+        }
+    });
+    connect(process, &QProcess::finished, this, [this, process](int exitCode, QProcess::ExitStatus exitStatus) {
+        process->deleteLater();
+        if (exitStatus != QProcess::NormalExit || exitCode != 0) {
+            const auto message = QString::fromUtf8(process->readAllStandardError()).trimmed();
+            qCWarning(PLASMAPASS_LOG, "Failed to decrypt password: %s", qUtf8Printable(message));
+            setError(i18n("Failed to decrypt password: %1", message));
+            return;
+        }
+
+        handlePlainText(process->readAllStandardOutput());
+    });
+
+    process->start(QStringLiteral("passage"), {QStringLiteral("show"), name});
+}
+
+void ProviderBase::handlePlainText(const QByteArray &plainText)
+{
+    const auto data = QString::fromUtf8(plainText);
+    if (data.isEmpty()) {
+        qCWarning(PLASMAPASS_LOG, "Password file is empty!");
+        setError(i18n("No password found"));
+        return;
+    }
+
+    const auto lines = QStringView(data).split(QLatin1Char('\n'));
+    for (const auto &line : lines) {
+        if (handleSecret(line) == HandlingResult::Stop) {
+            break;
+        }
+    }
+}
+
 bool ProviderBase::isValid() const
 {
     return !mSecret.isNull();
